//////////////////////////////////////////////////////////////////////////////////
// UTUIButtonGenericDrive
//////////////////////////////////////////////////////////////////////////////////

"use client";

// Global Imports
import { X } from "lucide-react";
import { useCallback, useEffect, useRef, useState } from "react";
import { generatePermittedFileTypes } from "uploadthing/client";

// Local Imports
import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Drawer,
  DrawerContent,
  DrawerDescription,
  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
  DrawerTrigger,
} from "@/components/ui/drawer";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { useMediaQuery } from "@/hooks/use-media-query";
import { useUploadThing } from "@/lib/uploadthing";
import { UTUIFileStatus, UTUIFunctionsProps } from "@/lib/uploadthing-ui-types";
import {
  capitalizeFirstLetter,
  formatBytes,
  getUploadedAmount,
} from "@/lib/uploadthing-ui-utils";
import { useGenericDriveStore } from "@/store/button-generic-drive-store";

// Body
export default function UTUIButtonGenericDrive({
  UTUIFunctionsProps,
  isDesktopMinWidth,
}: {
  UTUIFunctionsProps: UTUIFunctionsProps;
  isDesktopMinWidth?: string;
}) {
  // [1] Refs & States
  const fileInputRef = useRef<HTMLInputElement>(null);
  const { addFiles, openModel, files, resetFiles } = useGenericDriveStore();
  const abortControllerRef = useRef<AbortController | null>(null);

  // [2] Derived states
  const { routeConfig } = useUploadThing(UTUIFunctionsProps.fileRoute);
  const acceptedFileTypes = generatePermittedFileTypes(routeConfig)
    .fileTypes.map((fileType) => {
      if (fileType.includes("/")) {
        return fileType;
      } else {
        return `${fileType}/*`;
      }
    })
    .join(",");

  const [abortSignal, setAbortSignal] = useState<AbortSignal | undefined>(
    undefined,
  );

  // [3] Handlers
  const handleButtonClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    openModel();

    // Create a new AbortController for this upload
    abortControllerRef.current = new AbortController();
    setAbortSignal(abortControllerRef.current.signal);

    const selectedFiles = e.target.files;
    if (selectedFiles && selectedFiles.length > 0 && fileInputRef.current) {
      // Convert FileList to Array and add them to state
      addFiles(Array.from(selectedFiles));

      // Reset the input to allow selecting the same files again
      fileInputRef.current.value = "";
    }
  };

  function resetAbortController() {
    if (abortControllerRef.current) {
      resetFiles();
      abortControllerRef.current.abort();
      setAbortSignal(abortControllerRef.current.signal);
    }
  }

  // JSX
  return (
    <div className="flex flex-col gap-8 text-sm">
      {/* Hidden input for selecting files */}
      <input
        type="file"
        ref={fileInputRef}
        onChange={handleFileChange}
        style={{ display: "none" }}
        multiple
        accept={acceptedFileTypes}
      />
      {/* Button to trigger the file selection */}
      <Button className="w-fit" onClick={handleButtonClick}>
        Select Files to Upload
      </Button>
      <FileModel
        abortSignal={abortSignal}
        resetAbortController={resetAbortController}
        UTUIFunctionsProps={UTUIFunctionsProps}
        isDesktopMinWidth={isDesktopMinWidth}
      />
    </div>
  );
}

//////////////////////////////////////////////////////////////////////////////////
// File Model
//////////////////////////////////////////////////////////////////////////////////

function FileModel({
  abortSignal,
  resetAbortController,
  UTUIFunctionsProps,
  isDesktopMinWidth,
}: {
  abortSignal?: AbortSignal;
  resetAbortController: () => void;
  UTUIFunctionsProps: UTUIFunctionsProps;
  isDesktopMinWidth?: string;
}) {
  // [1] Refs & States & Callbacks
  const {
    files,
    displayModel,
    updateFileStatus,
    closeModel: closeModelStore,
    resetFiles,
  } = useGenericDriveStore();
  const [stopConfirmationModel, setStopConfirmationModel] = useState(false);
  const isDesktop = useMediaQuery(
    `(min-width: ${isDesktopMinWidth ? isDesktopMinWidth : "768px"})`,
  );

  const handleStatusChange = useCallback(
    (id: string, status: UTUIFileStatus, url?: string) => {
      updateFileStatus(id, status, url);
    },
    [updateFileStatus],
  );

  // [2] Derived State
  const isUploadComplete = files.every(
    (file) => file.status === "complete" || file.status === "error",
  );

  // [3] Handlers
  function closeModel() {
    if (isUploadComplete) {
      closeModelStore();
    } else {
      toggleIsStopConfirmationModel();
    }
  }

  function toggleIsStopConfirmationModel() {
    setStopConfirmationModel((cur) => !cur);
  }

  function onStopTransfers() {
    closeModelStore();
    resetFiles();
    closeStopConfirmationModel();

    resetAbortController();
  }

  function closeStopConfirmationModel() {
    setStopConfirmationModel(false);
  }

  function closeModelAfterUpload() {
    closeStopConfirmationModel();
    closeModel();
    resetFiles();
  }

  // [4] JSX (Desktop)
  if (isDesktop) {
    return (
      <AlertDialog open={displayModel} onOpenChange={closeModel}>
        <AlertDialogContent location="bottom-right" hideOverlay>
          <AlertDialogHeader>
            <AlertDialogTitle asChild>
              <div className="flex items-center justify-between">
                {isUploadComplete ? (
                  <p>
                    {files.length} file{files.length > 1 ? "s" : ""} uploaded
                  </p>
                ) : (
                  <p>
                    {files.length} file{files.length > 1 ? "s" : ""} uploading
                  </p>
                )}
                <div className="flex gap-2">
                  {!isUploadComplete ? (
                    <StopUploadConfirmation
                      filesSum={files.length}
                      open={stopConfirmationModel}
                      toggleOpen={toggleIsStopConfirmationModel}
                      onStopTransfers={onStopTransfers}
                      closeOpen={closeStopConfirmationModel}
                      isDesktopMinWidth={isDesktopMinWidth}
                    />
                  ) : (
                    <Button variant={"outline"} onClick={closeModelAfterUpload}>
                      <X className="stroke-1" />
                    </Button>
                  )}
                </div>
              </div>
            </AlertDialogTitle>
            <AlertDialogDescription asChild>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Name</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead className="text-right">Uploading</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {files.map((fileItem) => (
                    <FileRow
                      key={fileItem.id}
                      fileId={fileItem.id}
                      file={fileItem.file}
                      abortSignal={abortSignal}
                      onStatusChange={handleStatusChange}
                      status={fileItem.status}
                      UTUIFunctionsProps={UTUIFunctionsProps}
                    />
                  ))}
                </TableBody>
              </Table>
            </AlertDialogDescription>
          </AlertDialogHeader>
        </AlertDialogContent>
      </AlertDialog>
    );
  }

  // [4] JSX (Mobile)
  return (
    <Drawer open={displayModel} onOpenChange={closeModel}>
      <DrawerContent>
        <DrawerHeader className="text-left">
          <DrawerTitle asChild>
            <div className="flex items-center justify-between">
              {isUploadComplete ? (
                <p>
                  {files.length} file{files.length > 1 ? "s" : ""} uploaded
                </p>
              ) : (
                <p>
                  {files.length} file{files.length > 1 ? "s" : ""} uploading
                </p>
              )}
              <div className="flex gap-2">
                {!isUploadComplete ? (
                  <StopUploadConfirmation
                    filesSum={files.length}
                    open={stopConfirmationModel}
                    toggleOpen={toggleIsStopConfirmationModel}
                    onStopTransfers={onStopTransfers}
                    closeOpen={closeStopConfirmationModel}
                    isDesktopMinWidth={isDesktopMinWidth}
                  />
                ) : (
                  <Button variant={"outline"} onClick={closeModelAfterUpload}>
                    <X className="stroke-1" />
                  </Button>
                )}
              </div>
            </div>
          </DrawerTitle>
          <DrawerDescription asChild>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Name</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead className="text-right">Uploading</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {files.map((fileItem) => (
                  <FileRow
                    key={fileItem.id}
                    fileId={fileItem.id}
                    file={fileItem.file}
                    abortSignal={abortSignal}
                    onStatusChange={handleStatusChange}
                    status={fileItem.status}
                    UTUIFunctionsProps={UTUIFunctionsProps}
                  />
                ))}
              </TableBody>
            </Table>
          </DrawerDescription>
        </DrawerHeader>
      </DrawerContent>
    </Drawer>
  );
}

function StopUploadConfirmation({
  open,
  filesSum,
  isDesktopMinWidth,
  toggleOpen,
  closeOpen,
  onStopTransfers,
}: {
  open: boolean;
  filesSum: number;
  isDesktopMinWidth?: string;
  toggleOpen: () => void;
  closeOpen: () => void;
  onStopTransfers: () => void;
}) {
  const isDesktop = useMediaQuery(
    `(min-width: ${isDesktopMinWidth ? isDesktopMinWidth : "768px"})`,
  );

  // [1] JSX (Desktop)
  if (isDesktop) {
    return (
      <AlertDialog open={open} onOpenChange={toggleOpen}>
        <AlertDialogTrigger asChild>
          <Button variant={"outline"}>
            <X className="stroke-1" />
          </Button>
        </AlertDialogTrigger>

        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Stop transfers?</AlertDialogTitle>
            <AlertDialogDescription>
              There
              {`${filesSum > 1 ? " are " : " is "}${filesSum} file${
                filesSum > 1 ? "s" : ""
              }`}{" "}
              that still need to be transferred. Closing the transfer manager
              will end all operations
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter className="gap-2">
            <Button variant={"outline"} onClick={closeOpen}>
              Continue transfers
            </Button>
            <Button variant={"destructive"} onClick={onStopTransfers}>
              Stop transfers
            </Button>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    );
  }

  // [2] JSX (Mobile)
  return (
    <Drawer open={open} onOpenChange={toggleOpen}>
      <DrawerTrigger asChild>
        <Button variant={"outline"}>
          <X className="stroke-1" />
        </Button>
      </DrawerTrigger>

      <DrawerContent showOverlay={false}>
        <DrawerHeader className="text-left">
          <DrawerTitle>Stop transfers?</DrawerTitle>
          <DrawerDescription>
            There
            {`${filesSum > 1 ? " are " : " is "}${filesSum} file${
              filesSum > 1 ? "s" : ""
            }`}{" "}
            that still need to be transferred. Closing the transfer manager will
            end all operations
          </DrawerDescription>
        </DrawerHeader>
        <DrawerFooter>
          <Button variant={"outline"} onClick={closeOpen}>
            Continue transfers
          </Button>
          <Button variant={"destructive"} onClick={onStopTransfers}>
            Stop transfers
          </Button>
        </DrawerFooter>
      </DrawerContent>
    </Drawer>
  );
}

//////////////////////////////////////////////////////////////////////////////////
// File Row
//////////////////////////////////////////////////////////////////////////////////

interface FileUploaderProps {
  fileId: string;
  file: File;
  status: UTUIFileStatus;
  abortSignal?: AbortSignal;
  onStatusChange: (id: string, status: UTUIFileStatus, url?: string) => void;
  UTUIFunctionsProps: UTUIFunctionsProps;
}

function FileRow({
  fileId,
  file,
  status,
  abortSignal,
  onStatusChange,
  UTUIFunctionsProps,
}: FileUploaderProps) {
  // [1] State & Ref
  const [progress, setProgress] = useState(0);
  const isMounted = useRef(true);
  const hasStartedUpload = useRef(false);
  // [2] Uploadthing
  const { startUpload, isUploading } = useUploadThing(
    UTUIFunctionsProps.fileRoute,
    {
      uploadProgressGranularity: "fine",
      signal: abortSignal,
      onUploadProgress: (progress) => {
        if (isMounted.current) {
          setProgress(progress);

          // Your additional code here
          UTUIFunctionsProps.onUploadProgress?.(progress);
        }
      },
      onClientUploadComplete: (res) => {
        if (isMounted.current && res?.[0]) {
          onStatusChange(fileId, "complete", res[0].url);

          // Your additional code here
          UTUIFunctionsProps.onClientUploadComplete?.(res);
        }
      },
      onUploadError: (error) => {
        if (isMounted.current) {
          onStatusChange(fileId, "error");

          // Your additional code here
          UTUIFunctionsProps.onUploadError?.(error);
        }
      },
      onBeforeUploadBegin: UTUIFunctionsProps.onBeforeUploadBegin,
      onUploadBegin: UTUIFunctionsProps.onUploadBegin,
    },
  );

  // [3] Effects
  useEffect(() => {
    // Only start upload if we haven't already and no abort has happened
    if (!hasStartedUpload.current && !isUploading) {
      hasStartedUpload.current = true;

      startUpload([file]).catch(() => {
        // Handling the abort
        onStatusChange(fileId, "error");
      });

      onStatusChange(fileId, "uploading");
    }
  }, [fileId, file, startUpload, onStatusChange, isUploading]);

  // [4] JSX
  return (
    <TableRow>
      <TableCell className="max-w-48 truncate text-left font-medium">
        {file.name}
      </TableCell>
      <TableCell>
        <Badge
          variant={
            status === "complete"
              ? "success"
              : status === "error"
                ? "destructive"
                : "default"
          }
        >
          {capitalizeFirstLetter(status)}
        </Badge>
      </TableCell>
      <TableCell className="text-right">
        {getUploadedAmount(progress, file.size)} / {formatBytes(file.size)}
      </TableCell>
    </TableRow>
  );
}

// Global Imports

import { create } from "zustand";
import { createId } from "@paralleldrive/cuid2";
import { UTUIFileStatus, UTUIUploadFile } from "@/lib/uploadthing-ui-types";

// Local Imports

// Body
// [1] Types
interface FilesState {
  files: UTUIUploadFile[];
  displayModel: boolean;
  addFiles: (newFiles: File[]) => void;
  updateFileStatus: (id: string, status: UTUIFileStatus, url?: string) => void;
  resetFiles: () => void;
  openModel: () => void;
  closeModel: () => void;
  toggleModel: () => void;
}

// [2] Store
export const useGenericDriveStore = create<FilesState>()((set) => ({
  files: [],
  displayModel: false,
  addFiles: (newFiles) =>
    set((state) => ({
      files: [
        ...state.files,
        ...newFiles.map((file) => ({
          id: createId(),
          file,
          status: "pending" as UTUIFileStatus,
          createdAt: new Date(),
        })),
      ],
    })),
  updateFileStatus: (id, status, url) =>
    set((state) => ({
      files: state.files.map((item) =>
        item.id === id ? { ...item, status, url } : item,
      ),
    })),
  resetFiles: () =>
    set({
      files: [],
    }),
  openModel: () => set({ displayModel: true }),
  closeModel: () => set({ displayModel: false }),
  toggleModel: () => set((state) => ({ displayModel: !state.displayModel })),
}));

"use client";

import * as AlertDialogPrimitive from "@radix-ui/react-alert-dialog";
import * as React from "react";

import { buttonVariants } from "@/components/ui/button";
import { cn } from "@/lib/utils";

const AlertDialog = AlertDialogPrimitive.Root;

const AlertDialogTrigger = AlertDialogPrimitive.Trigger;

const AlertDialogPortal = AlertDialogPrimitive.Portal;

const AlertDialogOverlay = React.forwardRef<
  React.ElementRef<typeof AlertDialogPrimitive.Overlay>,
  React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Overlay>
>(({ className, ...props }, ref) => (
  <AlertDialogPrimitive.Overlay
    className={cn(
      "fixed inset-0 z-50 bg-black/80 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0",
      className,
    )}
    {...props}
    ref={ref}
  />
));
AlertDialogOverlay.displayName = AlertDialogPrimitive.Overlay.displayName;

const AlertDialogContent = React.forwardRef<
  React.ElementRef<typeof AlertDialogPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Content> & {
    location?: "default" | "bottom-right";
    hideOverlay?: boolean;
  }
>(({ className, location = "default", hideOverlay = false, ...props }, ref) => (
  <AlertDialogPortal>
    {hideOverlay ? null : <AlertDialogOverlay />}
    <AlertDialogPrimitive.Content
      ref={ref}
      className={cn(
        "fixed z-50 grid w-full max-w-lg gap-4 border bg-background p-6 shadow-lg duration-200 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 sm:rounded-lg",
        {
          "bottom-[5%] right-[5%] translate-x-[5%] translate-y-[5%] data-[state=closed]:slide-out-to-bottom-[48%] data-[state=closed]:slide-out-to-right-1/2 data-[state=open]:slide-in-from-bottom-[48%] data-[state=open]:slide-in-from-right-1/2":
            location === "bottom-right",
        },
        {
          "left-[50%] top-[50%] translate-x-[-50%] translate-y-[-50%] data-[state=closed]:slide-out-to-left-1/2 data-[state=closed]:slide-out-to-top-[48%] data-[state=open]:slide-in-from-left-1/2 data-[state=open]:slide-in-from-top-[48%]":
            location === "default",
        },
        className,
      )}
      {...props}
    />
  </AlertDialogPortal>
));
AlertDialogContent.displayName = AlertDialogPrimitive.Content.displayName;

const AlertDialogHeader = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    className={cn(
      "flex flex-col space-y-2 text-center sm:text-left",
      className,
    )}
    {...props}
  />
);
AlertDialogHeader.displayName = "AlertDialogHeader";

const AlertDialogFooter = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    className={cn(
      "flex flex-col-reverse sm:flex-row sm:justify-end sm:space-x-2",
      className,
    )}
    {...props}
  />
);
AlertDialogFooter.displayName = "AlertDialogFooter";

const AlertDialogTitle = React.forwardRef<
  React.ElementRef<typeof AlertDialogPrimitive.Title>,
  React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Title>
>(({ className, ...props }, ref) => (
  <AlertDialogPrimitive.Title
    ref={ref}
    className={cn("text-lg font-semibold", className)}
    {...props}
  />
));
AlertDialogTitle.displayName = AlertDialogPrimitive.Title.displayName;

const AlertDialogDescription = React.forwardRef<
  React.ElementRef<typeof AlertDialogPrimitive.Description>,
  React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Description>
>(({ className, ...props }, ref) => (
  <AlertDialogPrimitive.Description
    ref={ref}
    className={cn("text-sm text-muted-foreground", className)}
    {...props}
  />
));
AlertDialogDescription.displayName =
  AlertDialogPrimitive.Description.displayName;

const AlertDialogAction = React.forwardRef<
  React.ElementRef<typeof AlertDialogPrimitive.Action>,
  React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Action>
>(({ className, ...props }, ref) => (
  <AlertDialogPrimitive.Action
    ref={ref}
    className={cn(buttonVariants(), className)}
    {...props}
  />
));
AlertDialogAction.displayName = AlertDialogPrimitive.Action.displayName;

const AlertDialogCancel = React.forwardRef<
  React.ElementRef<typeof AlertDialogPrimitive.Cancel>,
  React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Cancel>
>(({ className, ...props }, ref) => (
  <AlertDialogPrimitive.Cancel
    ref={ref}
    className={cn(
      buttonVariants({ variant: "outline" }),
      "mt-2 sm:mt-0",
      className,
    )}
    {...props}
  />
));
AlertDialogCancel.displayName = AlertDialogPrimitive.Cancel.displayName;

export {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogOverlay,
  AlertDialogPortal,
  AlertDialogTitle,
  AlertDialogTrigger,
};

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

const badgeVariants = cva(
  "inline-flex items-center rounded-md border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2",
  {
    variants: {
      variant: {
        default:
          "border-transparent bg-primary text-primary-foreground shadow hover:bg-primary/80",
        secondary:
          "border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80",
        destructive:
          "border-transparent bg-destructive text-destructive-foreground shadow hover:bg-destructive/80",
        outline: "text-foreground",
        success:
          "border-transparent bg-chart-2 text-background shadow hover:bg-chart-2/80",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
);

export interface BadgeProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof badgeVariants> {}

function Badge({ className, variant, ...props }: BadgeProps) {
  return (
    <div className={cn(badgeVariants({ variant }), className)} {...props} />
  );
}

export { Badge, badgeVariants };

